mapper.select:
SELECT user_id AS userId, launch_date AS launchDate
FROM app_launch_daily
WHERE launch_date BETWEEN #{from} AND #{to}

SELECT s.stat_hour AS statHour, s.post_id AS postId, s.board_id AS boardId, b.name AS boardName, p.title AS title, s.read_scope AS readScope, s.rank_no AS rankNo, s.is_trending AS isTrending, s.raw_score AS rawScore, s.baseline_score AS baselineScore, s.spike_ratio AS spikeRatio, s.final_score AS finalScore, s.view_delta AS viewDelta, s.like_delta AS likeDelta, s.comment_delta AS commentDelta, s.view_count AS viewCount, s.like_count AS likeCount, s.comment_count AS commentCount FROM stats_post_hourly s JOIN boards b ON b.board_id = s.board_id LEFT JOIN posts p ON p.post_id = s.post_id WHERE s.stat_hour >= DATE_SUB(NOW(), INTERVAL #{hours} HOUR)
AND s.is_trending = 1
ORDER BY s.stat_hour DESC, s.rank_no IS NULL, s.rank_no, s.final_score DESC LIMIT #{limit}
